{{ config(
            materialized='table',
                post_hook={
                    "sql": "CREATE OR REPLACE TEMPORARY TABLE prd_db.justherbs._tmp_retention_base AS SELECT customer_id_final, order_id, acquisition_product, acquisition_product_category, Acquisition_coupon, acquisition_channel, acquisition_marketplace, shop_name, product_name, selling_price, first_complete_order_date::DATE AS Acquisition_Date, LAST_DAY(first_complete_order_date::DATE) AS acq_month_end, LAST_DAY(order_date) AS ord_month_end, DATEDIFF(month, first_complete_order_date::DATE, order_date) AS month_diff, CASE WHEN acquisition_product = product_name THEN 1 ELSE 0 END AS is_same_product, CASE WHEN order_date::DATE > first_complete_order_date::DATE THEN 1 ELSE 0 END AS is_after_acq FROM prd_db.justherbs.dwh_SALES_CONSOLIDATED WHERE LOWER(marketplace) LIKE \'%shopify%\' AND customer_id_final IS NOT NULL AND LOWER(order_status) <> \'cancelled\' AND DATEDIFF(month, first_complete_order_date::DATE, order_date) BETWEEN 0 AND 12; CREATE OR REPLACE TEMPORARY TABLE prd_db.justherbs._tmp_cust_dedup AS SELECT acq_month_end, acquisition_channel, acquisition_marketplace, acquisition_product, acquisition_product_category, acquisition_coupon, shop_name, customer_id_final, month_diff, MAX(is_same_product) AS is_same_product, MAX(is_after_acq) AS is_after_acq FROM prd_db.justherbs._tmp_retention_base GROUP BY 1,2,3,4,5,6,7,8,9; CREATE OR REPLACE TEMPORARY TABLE prd_db.justherbs._tmp_order_dedup AS SELECT acq_month_end, acquisition_channel, acquisition_marketplace, acquisition_product, acquisition_product_category, acquisition_coupon, shop_name, order_id, month_diff, MAX(is_same_product) AS is_same_product FROM prd_db.justherbs._tmp_retention_base GROUP BY 1,2,3,4,5,6,7,8,9; CREATE OR REPLACE TEMPORARY TABLE prd_db.justherbs._tmp_sales_agg AS SELECT acq_month_end, acquisition_channel, acquisition_marketplace, acquisition_product, acquisition_product_category, acquisition_coupon, shop_name, month_diff, is_same_product, SUM(selling_price) AS selling_price FROM prd_db.justherbs._tmp_retention_base GROUP BY 1,2,3,4,5,6,7,8,9; CREATE OR REPLACE TABLE prd_db.justherbs.dwh_CUSTOMER_RETENTION AS WITH cust_agg AS ( SELECT acq_month_end, acquisition_channel, acquisition_marketplace, acquisition_product, acquisition_product_category, acquisition_coupon, shop_name, COUNT(DISTINCT customer_id_final) AS total_customers, COUNT(CASE WHEN month_diff <> 0 THEN customer_id_final END) AS mn_c, COUNT(CASE WHEN is_same_product = 1 AND month_diff <> 0 THEN customer_id_final END) AS product_mn_c, COUNT(CASE WHEN month_diff = 1 THEN 1 END) AS m2_c, COUNT(CASE WHEN month_diff = 2 THEN 1 END) AS m3_c, COUNT(CASE WHEN month_diff = 3 THEN 1 END) AS m4_c, COUNT(CASE WHEN month_diff = 4 THEN 1 END) AS m5_c, COUNT(CASE WHEN month_diff = 5 THEN 1 END) AS m6_c, COUNT(CASE WHEN month_diff = 6 THEN 1 END) AS m7_c, COUNT(CASE WHEN month_diff = 7 THEN 1 END) AS m8_c, COUNT(CASE WHEN month_diff = 8 THEN 1 END) AS m9_c, COUNT(CASE WHEN month_diff = 9 THEN 1 END) AS m10_c, COUNT(CASE WHEN month_diff = 10 THEN 1 END) AS m11_c, COUNT(CASE WHEN month_diff = 11 THEN 1 END) AS m12_c, COUNT(CASE WHEN is_same_product = 1 AND month_diff = 1 THEN 1 END) AS product_m2_c, COUNT(CASE WHEN is_same_product = 1 AND month_diff = 2 THEN 1 END) AS product_m3_c, COUNT(CASE WHEN is_same_product = 1 AND month_diff = 3 THEN 1 END) AS product_m4_c, COUNT(CASE WHEN is_same_product = 1 AND month_diff = 4 THEN 1 END) AS product_m5_c, COUNT(CASE WHEN is_same_product = 1 AND month_diff = 5 THEN 1 END) AS product_m6_c, COUNT(CASE WHEN is_same_product = 1 AND month_diff = 6 THEN 1 END) AS product_m7_c, COUNT(CASE WHEN is_same_product = 1 AND month_diff = 7 THEN 1 END) AS product_m8_c, COUNT(CASE WHEN is_same_product = 1 AND month_diff = 8 THEN 1 END) AS product_m9_c, COUNT(CASE WHEN is_same_product = 1 AND month_diff = 9 THEN 1 END) AS product_m10_c, COUNT(CASE WHEN is_same_product = 1 AND month_diff = 10 THEN 1 END) AS product_m11_c, COUNT(CASE WHEN is_same_product = 1 AND month_diff = 11 THEN 1 END) AS product_m12_c FROM prd_db.justherbs._tmp_cust_dedup GROUP BY 1,2,3,4,5,6,7 ), cust_cumul AS ( SELECT acq_month_end, acquisition_channel, acquisition_marketplace, acquisition_product, acquisition_product_category, acquisition_coupon, shop_name, COUNT(DISTINCT CASE WHEN month_diff = 0 AND is_after_acq = 1 THEN customer_id_final END) AS product_category_m1_all_c, COUNT(DISTINCT CASE WHEN month_diff BETWEEN 0 AND 3 AND is_after_acq = 1 THEN customer_id_final END) AS product_category_m3_all_c, COUNT(DISTINCT CASE WHEN month_diff BETWEEN 0 AND 6 AND is_after_acq = 1 THEN customer_id_final END) AS product_category_m6_all_c, COUNT(DISTINCT CASE WHEN month_diff BETWEEN 0 AND 9 AND is_after_acq = 1 THEN customer_id_final END) AS product_Category_m9_all_c, COUNT(DISTINCT CASE WHEN month_diff BETWEEN 0 AND 12 AND is_after_acq = 1 THEN customer_id_final END) AS product_Category_m12_all_c FROM prd_db.justherbs._tmp_cust_dedup WHERE is_after_acq = 1 GROUP BY 1,2,3,4,5,6,7 ), order_agg AS ( SELECT acq_month_end, acquisition_channel, acquisition_marketplace, acquisition_product, acquisition_product_category, acquisition_coupon, shop_name, COUNT(CASE WHEN month_diff = 0 THEN 1 END) AS total_orders, COUNT(CASE WHEN month_diff <> 0 THEN 1 END) AS mn_o, COUNT(CASE WHEN is_same_product = 1 AND month_diff <> 0 THEN 1 END) AS product_mn_o, COUNT(CASE WHEN month_diff = 1 THEN 1 END) AS m2_o, COUNT(CASE WHEN month_diff = 2 THEN 1 END) AS m3_o, COUNT(CASE WHEN month_diff = 3 THEN 1 END) AS m4_o, COUNT(CASE WHEN month_diff = 4 THEN 1 END) AS m5_o, COUNT(CASE WHEN month_diff = 5 THEN 1 END) AS m6_o, COUNT(CASE WHEN month_diff = 6 THEN 1 END) AS m7_o, COUNT(CASE WHEN month_diff = 7 THEN 1 END) AS m8_o, COUNT(CASE WHEN month_diff = 8 THEN 1 END) AS m9_o, COUNT(CASE WHEN month_diff = 9 THEN 1 END) AS m10_o, COUNT(CASE WHEN month_diff = 10 THEN 1 END) AS m11_o, COUNT(CASE WHEN month_diff = 11 THEN 1 END) AS m12_o, COUNT(CASE WHEN is_same_product = 1 AND month_diff = 1 THEN 1 END) AS product_m2_o, COUNT(CASE WHEN is_same_product = 1 AND month_diff = 2 THEN 1 END) AS product_m3_o, COUNT(CASE WHEN is_same_product = 1 AND month_diff = 3 THEN 1 END) AS product_m4_o, COUNT(CASE WHEN is_same_product = 1 AND month_diff = 4 THEN 1 END) AS product_m5_o, COUNT(CASE WHEN is_same_product = 1 AND month_diff = 5 THEN 1 END) AS product_m6_o, COUNT(CASE WHEN is_same_product = 1 AND month_diff = 6 THEN 1 END) AS product_m7_o, COUNT(CASE WHEN is_same_product = 1 AND month_diff = 7 THEN 1 END) AS product_m8_o, COUNT(CASE WHEN is_same_product = 1 AND month_diff = 8 THEN 1 END) AS product_m9_o, COUNT(CASE WHEN is_same_product = 1 AND month_diff = 9 THEN 1 END) AS product_m10_o, COUNT(CASE WHEN is_same_product = 1 AND month_diff = 10 THEN 1 END) AS product_m11_o, COUNT(CASE WHEN is_same_product = 1 AND month_diff = 11 THEN 1 END) AS product_m12_o FROM prd_db.justherbs._tmp_order_dedup GROUP BY 1,2,3,4,5,6,7 ), sales_agg AS ( SELECT acq_month_end, acquisition_channel, acquisition_marketplace, acquisition_product, acquisition_product_category, acquisition_coupon, shop_name, SUM(CASE WHEN month_diff = 0 THEN selling_price END) AS total_sales, SUM(CASE WHEN month_diff <> 0 THEN selling_price END) AS mn_s, SUM(CASE WHEN is_same_product = 1 AND month_diff <> 0 THEN selling_price END) AS product_mn_s, SUM(CASE WHEN month_diff = 1 THEN selling_price END) AS m2_s, SUM(CASE WHEN month_diff = 2 THEN selling_price END) AS m3_s, SUM(CASE WHEN month_diff = 3 THEN selling_price END) AS m4_s, SUM(CASE WHEN month_diff = 4 THEN selling_price END) AS m5_s, SUM(CASE WHEN month_diff = 5 THEN selling_price END) AS m6_s, SUM(CASE WHEN month_diff = 6 THEN selling_price END) AS m7_s, SUM(CASE WHEN month_diff = 7 THEN selling_price END) AS m8_s, SUM(CASE WHEN month_diff = 8 THEN selling_price END) AS m9_s, SUM(CASE WHEN month_diff = 9 THEN selling_price END) AS m10_s, SUM(CASE WHEN month_diff = 10 THEN selling_price END) AS m11_s, SUM(CASE WHEN month_diff = 11 THEN selling_price END) AS m12_s, SUM(CASE WHEN is_same_product = 1 AND month_diff = 1 THEN selling_price END) AS product_m2_s, SUM(CASE WHEN is_same_product = 1 AND month_diff = 2 THEN selling_price END) AS product_m3_s, SUM(CASE WHEN is_same_product = 1 AND month_diff = 3 THEN selling_price END) AS product_m4_s, SUM(CASE WHEN is_same_product = 1 AND month_diff = 4 THEN selling_price END) AS product_m5_s, SUM(CASE WHEN is_same_product = 1 AND month_diff = 5 THEN selling_price END) AS product_m6_s, SUM(CASE WHEN is_same_product = 1 AND month_diff = 6 THEN selling_price END) AS product_m7_s, SUM(CASE WHEN is_same_product = 1 AND month_diff = 7 THEN selling_price END) AS product_m8_s, SUM(CASE WHEN is_same_product = 1 AND month_diff = 8 THEN selling_price END) AS product_m9_s, SUM(CASE WHEN is_same_product = 1 AND month_diff = 9 THEN selling_price END) AS product_m10_s, SUM(CASE WHEN is_same_product = 1 AND month_diff = 10 THEN selling_price END) AS product_m11_s, SUM(CASE WHEN is_same_product = 1 AND month_diff = 11 THEN selling_price END) AS product_m12_s FROM prd_db.justherbs._tmp_sales_agg GROUP BY 1,2,3,4,5,6,7 ) SELECT YEAR(c.acq_month_end) AS Acquisition_Year, MONTHNAME(c.acq_month_end) AS Acquisition_Month, c.acq_month_end AS Acquisition_Month_LastDate, c.Acquisition_Channel, c.Acquisition_Marketplace, c.Acquisition_Product, c.acquisition_product_category AS Acquisition_Category, c.Acquisition_coupon, c.Shop_Name AS Purchase_Marketplace, c.total_customers, o.total_orders, s.total_sales, c.mn_c, o.mn_o, s.mn_s, c.product_mn_c, o.product_mn_o, s.product_mn_s, c.m2_c, c.m3_c, c.m4_c, c.m5_c, c.m6_c, c.m7_c, c.m8_c, c.m9_c, c.m10_c, c.m11_c, c.m12_c, COALESCE(cc.product_category_m1_all_c, 0) AS product_category_m1_all_c, COALESCE(cc.product_category_m3_all_c, 0) AS product_category_m3_all_c, COALESCE(cc.product_category_m6_all_c, 0) AS product_category_m6_all_c, COALESCE(cc.product_Category_m9_all_c, 0) AS product_Category_m9_all_c, COALESCE(cc.product_Category_m12_all_c, 0) AS product_Category_m12_all_c, o.m2_o, o.m3_o, o.m4_o, o.m5_o, o.m6_o, o.m7_o, o.m8_o, o.m9_o, o.m10_o, o.m11_o, o.m12_o, s.m2_s, s.m3_s, s.m4_s, s.m5_s, s.m6_s, s.m7_s, s.m8_s, s.m9_s, s.m10_s, s.m11_s, s.m12_s, c.product_m2_c, c.product_m3_c, c.product_m4_c, c.product_m5_c, c.product_m6_c, c.product_m7_c, c.product_m8_c, c.product_m9_c, c.product_m10_c, c.product_m11_c, c.product_m12_c, o.product_m2_o, o.product_m3_o, o.product_m4_o, o.product_m5_o, o.product_m6_o, o.product_m7_o, o.product_m8_o, o.product_m9_o, o.product_m10_o, o.product_m11_o, o.product_m12_o, s.product_m2_s, s.product_m3_s, s.product_m4_s, s.product_m5_s, s.product_m6_s, s.product_m7_s, s.product_m8_s, s.product_m9_s, s.product_m10_s, s.product_m11_s, s.product_m12_s FROM cust_agg c LEFT JOIN cust_cumul cc ON c.acq_month_end = cc.acq_month_end AND c.acquisition_channel = cc.acquisition_channel AND c.acquisition_marketplace = cc.acquisition_marketplace AND c.acquisition_product = cc.acquisition_product AND c.acquisition_product_category = cc.acquisition_product_category AND c.acquisition_coupon = cc.acquisition_coupon AND c.shop_name = cc.shop_name LEFT JOIN order_agg o ON c.acq_month_end = o.acq_month_end AND c.acquisition_channel = o.acquisition_channel AND c.acquisition_marketplace = o.acquisition_marketplace AND c.acquisition_product = o.acquisition_product AND c.acquisition_product_category = o.acquisition_product_category AND c.acquisition_coupon = o.acquisition_coupon AND c.shop_name = o.shop_name LEFT JOIN sales_agg s ON c.acq_month_end = s.acq_month_end AND c.acquisition_channel = s.acquisition_channel AND c.acquisition_marketplace = s.acquisition_marketplace AND c.acquisition_product = s.acquisition_product AND c.acquisition_product_category = s.acquisition_product_category AND c.acquisition_coupon = s.acquisition_coupon AND c.shop_name = s.shop_name; DROP TABLE IF EXISTS prd_db.justherbs._tmp_retention_base; DROP TABLE IF EXISTS prd_db.justherbs._tmp_cust_dedup; DROP TABLE IF EXISTS prd_db.justherbs._tmp_order_dedup; DROP TABLE IF EXISTS prd_db.justherbs._tmp_sales_agg; create or replace table prd_db.justherbs.dwh_monthly_retention as with cust as ( select date_trunc(\'month\', order_date::date) Date_Start, month(date_start) month, year(date_Start) year, customer_id_final, max( case when lower(new_customer_flag_month) = \'new\' then 1 else 0 end ) as new_flag, max( case when lower(new_customer_flag_month) = \'repeat\' then 1 else 0 end ) as repeat_flag from prd_db.justherbs.dwh_SALES_CONSOLIDATED where lower(shop_name) like any (\'%shopify%\', \'%cred%\') and lower(order_status) <> \'cancelled\' group by 1, 2, 3, 4 ), months as ( select distinct date_trunc(\'month\', order_date::date) date_start from prd_db.justherbs.dwh_SALES_CONSOLIDATED where lower(shop_name) like any (\'%shopify%\', \'%cred%\') ), All_Customers as ( select date_trunc(\'month\', Date_Start::date) Date_Start, month(date_start) month, year(date_Start) year, count(distinct customer_id_final) All_customers, sum(new_flag) TM_New_Customers, sum(repeat_flag) TM_Repeat_Customers from cust group by 1, 2, 3 ), All_Customers_Till_LM as ( select a.month, a.year, a.date_start, All_customers_Till_LM, count(distinct c.customer_id_final) All_customers_LTM, count( distinct case when c.new_flag = 1 then c.customer_id_final end ) as New_customers_LTM from ( select month(a.date_start) month, year(a.date_Start) year, a.date_start, count(distinct b.customer_id_final) All_customers_Till_LM from months a left join cust b on b.Date_Start < a.date_start group by 1, 2, 3 ) a left join cust c on c.Date_Start < a.date_start and c.date_start >= date_trunc(\'month\', a.date_start -365) group by 1, 2, 3, 4 ) Select TM.Date_Start, TM.month, TM.year, TM.All_customers TM_All_customers,( sum(TM.all_customers) over ( partition by 1 order by TM.date_start asc rows between 1 preceding and current row ) - TM.All_customers ) All_Customers_LM, TM.TM_New_Customers,( sum(TM.TM_New_Customers) over ( partition by 1 order by TM.date_start asc rows between 1 preceding and current row ) - TM.TM_New_Customers ) LM_New_Customers, TM.TM_Repeat_Customers, TLM.All_customers_Till_LM, TLM.All_customers_LTM, TLM.New_customers_LTM from All_customers TM left join All_Customers_Till_LM TLM on TM.date_Start = TLM.date_Start;",
                    "transaction": true
                }
            ) }}
